/* ----- Responsive Movie Grid & Movie Card Styles (CineDiscover) ----- */

/* Grid Layout for movie cards */
.movie-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 28px;
  margin-top: 0;
}

.movie-card {
  background: var(--card-bg);
  border-radius: 12px;
  min-height: 280px;
  box-shadow: 0 2px 20px 0 #18181c33;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 20px;
  text-align: center;
  transition: box-shadow 0.17s cubic-bezier(.63,.04,.21,.93), 
              transform 0.13s cubic-bezier(.57,.18,.29,.94);
  position: relative;
}

.movie-card:hover, .movie-card:focus-within {
  box-shadow: 0 4px 25px 0 #e509141a, 0 2px 24px 0 #18181c33;
  transform: translateY(-3px) scale(1.012);
  z-index: 2;
}

/* Poster image */
.movie-card img {
  width: 110px;
  height: 165px;
  object-fit: cover;
  border-radius: 10px;
  margin-bottom: 18px;
  background: #282838;
  box-shadow: 0 1px 6px 0 #22222a66;
  transition: filter 0.12s;
}

.movie-card img[alt*="No Image"] {
  filter: grayscale(0.15);
  background: #23232a;
}

/* Title and year text */
.movie-card .movie-title {
  font-weight: 600;
  font-size: 15px;
  color: #fff;
  margin-bottom: 6px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 130px;
}
.movie-card .movie-year {
  font-size: 13px;
  color: var(--text-secondary);
  margin-bottom: 12px;
}

/* Buttons within card */
.movie-card .btn {
  font-weight: 500;
  font-size: 13px;
  padding: 7px 12px;
  border-radius: 4px;
  cursor: pointer;
  border: 1px solid #444;
  background: #282828;
  color: #fff;
  margin: 0;
  transition: background 0.17s, border 0.17s, color 0.14s;
}
.movie-card .btn:focus, .movie-card .btn:active {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}
.movie-card .btn.watchlist-active {
  background: var(--accent);
  border: 2px solid var(--accent);
  color: #fff;
}
.movie-card .btn.showtimes {
  background: #23232a;
  color: var(--accent);
  border: 1px solid var(--accent);
}
.movie-card .btn.showtimes:hover {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

/* Layout buttons horizontally */
.movie-card-actions {
  display: flex;
  gap: 8px;
  margin-top: auto;
}

/* Responsive tweaks */
@media (max-width: 770px) {
  .container {
    padding: 0 9px;
  }
  .movie-grid {
    gap: 16px;
  }
  .movie-card {
    padding: 13px 6px 19px 6px;
    min-height: 238px;
  }
  .movie-card img {
    width: 82px;
    height: 122px;
    margin-bottom: 10px;
  }
  .movie-card .movie-title {
    max-width: 95px;
    font-size: 14px;
  }
}

/* On small screens: switch grid to single or 2 columns, larger touch targets */
@media (max-width: 540px) {
  .movie-grid {
    grid-template-columns: repeat(auto-fit, minmax(92vw, 1fr));
    gap: 9vw;
  }
  .movie-card {
    min-width: 0;
    width: 91vw;
    max-width: 99vw;
    padding: 12px 4px 18px 4px;
  }
  .movie-card img {
    width: 95px;
    height: 138px;
  }
}

/* Spinner accessibility for dark bg */
.spinner {
  border: 4px solid var(--accent);
  border-top: 4px solid transparent;
  border-radius: 50%;
  animation: spin 1.1s linear infinite;
}

@keyframes spin {
  0% { transform: rotate(0deg);}
  100% { transform: rotate(360deg);}
}
